/**
 * Production build script - bundles the application with esbuild
 * Creates a distributable bundle in the dist/ directory
 */
import { build } from 'esbuild';
import { existsSync, mkdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';

const DIST_DIR = join(process.cwd(), 'dist');

// Clean and create dist directory
if (existsSync(DIST_DIR)) {
  rmSync(DIST_DIR, { recursive: true, force: true });
}
mkdirSync(DIST_DIR, { recursive: true });

async function buildApp() {
  try {
    // Build main CLI entry point
    await build({
      entryPoints: ['src/cli.ts'],
      bundle: true,
      platform: 'node',
      target: 'node20',
      format: 'esm',
      outfile: join(DIST_DIR, 'cli.js'),
      sourcemap: true,
      minify: true,
      treeShaking: true,
      external: [
        // Keep native modules external
        'playwright-core',
        '@hono/node-server',
      ],
      banner: {
        js: '// Qwen Proxy Gateway - Production Bundle\n// Generated by npm run build\n',
      },
    });

    // Copy bin/qg.js to dist
    const { readFileSync, writeFileSync } = await import('node:fs');
    const binContent = readFileSync('bin/qg.js', 'utf8');
    writeFileSync(join(DIST_DIR, 'qg.js'), binContent);

    console.log('✅ Build completed successfully!');
    console.log(`📦 Output directory: ${DIST_DIR}`);
    console.log('🚀 Run with: node dist/cli.js start');
  } catch (error) {
    console.error('❌ Build failed:', error);
    process.exit(1);
  }
}

buildApp();
